changeSet.sql:
CREATE TABLE IF NOT EXISTS app.template ( template_id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL, company_id BIGINT NOT NULL, delete_flag INTEGER DEFAULT 0, created_by BIGINT, created_date_time TIMESTAMPTZ(6), updated_by BIGINT, updated_date_time TIMESTAMPTZ(6),
CONSTRAINT fk_template_company FOREIGN KEY (company_id) REFERENCES app.company(company_id) ON DELETE CASCADE,
CONSTRAINT uq_template_name_company UNIQUE (name, company_id) );

CREATE TABLE IF NOT EXISTS app.template_part_attribute ( id BIGSERIAL PRIMARY KEY, template_id BIGINT NOT NULL, attribute_id BIGINT NOT NULL, delete_flag INTEGER DEFAULT 0, created_by BIGINT, created_date_time TIMESTAMPTZ(6), updated_by BIGINT, updated_date_time TIMESTAMPTZ(6),
CONSTRAINT fk_template FOREIGN KEY (template_id) REFERENCES app.template(template_id) ON DELETE CASCADE,
CONSTRAINT fk_part_attribute FOREIGN KEY (attribute_id) REFERENCES app.part_attribute(attribute_id) ON DELETE CASCADE );
